"""Demo 1: Closed-form invariant and quadratic growth of the anti-Fibonacci sequence."""
from __future__ import annotations
from typing import List, Tuple


def anti_fib(n_max: int) -> List[int]:
    """A(0)=1, A(n+1)=A(n)+n, returned as a list up to index n_max."""
    seq: List[int] = [1]
    for k in range(n_max):
        seq.append(seq[-1] + k)
    return seq


def closed(n: int) -> int:
    """Closed form A(n) = 1 + n(n-1)/2."""
    return 1 + n * (n - 1) // 2


def check_invariant(n_max: int) -> bool:
    """Verify 2*A(n) + n = n^2 + 2 and the closed form for 0 <= n <= n_max."""
    seq = anti_fib(n_max)
    return all(2 * seq[n] + n == n * n + 2 and seq[n] == closed(n)
               for n in range(n_max + 1))


def density(indices: List[int]) -> List[Tuple[int, int, float]]:
    """Return (n, A(n), A(n)/n^2), which tends to 1/2."""
    return [(n, closed(n), closed(n) / (n * n)) for n in indices]


if __name__ == "__main__":
    print("First terms:", anti_fib(11))
    print("Invariant 2A(n)+n=n^2+2 holds to n=5000:", check_invariant(5000))
    for n, a, r in density([10, 100, 1000, 10 ** 6]):
        print(f"n={n:>8}  A(n)={a:>15}  A(n)/n^2={r:.8f}  (-> 0.5)")

"""Demo 2: The consecutive ratio converges to 1, avoiding the golden ratio."""
from __future__ import annotations
from typing import List, Tuple

PHI: float = (1.0 + 5.0 ** 0.5) / 2.0  # golden ratio ~ 1.6180339887


def closed(n: int) -> int:
    """A(n) = 1 + n(n-1)/2."""
    return 1 + n * (n - 1) // 2


def ratio(n: int) -> float:
    """A(n+1)/A(n) = 1 + 2n/(n^2 - n + 2)."""
    return closed(n + 1) / closed(n)


def ratio_trajectory(n_max: int) -> List[Tuple[int, float]]:
    """Ratios for n = 0..n_max; monotone decreasing to 1 after the second term."""
    return [(n, ratio(n)) for n in range(n_max + 1)]


def is_monotone_decreasing_from(n0: int, n_max: int) -> bool:
    """Check A(n+1)/A(n) strictly decreases for n0 <= n < n_max."""
    return all(ratio(n) > ratio(n + 1) for n in range(n0, n_max))


def distance_to_phi(n: int) -> float:
    """How far the ratio sits from the golden ratio (it never reaches phi)."""
    return abs(ratio(n) - PHI)


if __name__ == "__main__":
    for n, r in ratio_trajectory(10):
        print(f"n={n:>2}  ratio={r:.6f}")
    print("Monotone decreasing for 2<=n<10000:", is_monotone_decreasing_from(2, 10000))
    for n in (100, 10_000, 1_000_000):
        print(f"n={n:>8}  ratio={ratio(n):.10f}  |ratio - phi|={distance_to_phi(n):.6f}")
    print(f"Ratio limit = 1; phi = {PHI:.10f}; the gap phi-1 = {PHI-1:.6f} is never closed.")

"""Demo 3: The Fibonacci-coincidence set is exactly {0, 3}, with undershoot after."""
from __future__ import annotations
from typing import Dict, List


def anti_fib(n_max: int) -> List[int]:
    """A(0)=1, A(n+1)=A(n)+n up to index n_max."""
    seq: List[int] = [1]
    for k in range(n_max):
        seq.append(seq[-1] + k)
    return seq


def scan_fibonacci_relation(n_max: int) -> Dict[str, List[int]]:
    """Classify each n in [0, n_max] by A(n+2) vs A(n+1)+A(n).

    Returns dict with keys 'equal', 'undershoot', 'overshoot'.
    Theory predicts equal = {0, 3}, undershoot = {n >= 4}, overshoot = {1, 2}
    (the sequence briefly overshoots the Fibonacci sum before settling below it).
    """
    seq = anti_fib(n_max + 2)
    out: Dict[str, List[int]] = {"equal": [], "undershoot": [], "overshoot": []}
    for n in range(n_max + 1):
        lhs, rhs = seq[n + 2], seq[n + 1] + seq[n]
        if lhs == rhs:
            out["equal"].append(n)
        elif lhs < rhs:
            out["undershoot"].append(n)
        else:
            out["overshoot"].append(n)
    return out


def coincidence_via_quadratic() -> List[int]:
    """The relation reduces to A(n)=n+1, i.e. n(n-3)=0; solve directly over N."""
    return [n for n in range(4) if n * (n - 3) == 0]


if __name__ == "__main__":
    res = scan_fibonacci_relation(100)
    print("equal indices (expect [0, 3]):", res["equal"])
    print("first undershoot index (expect 4):", res["undershoot"][0])
    print("overshoot indices (expect [1, 2]):", res["overshoot"])
    print("via reduction n(n-3)=0:", coincidence_via_quadratic())

